302	  /**
303	   * Returns the result of dividing {@code p} by {@code q}, rounding using the specified {@code
304	   * RoundingMode}. If the {@code RoundingMode} is {@link RoundingMode#DOWN}, then this method is
305	   * equivalent to regular Java division, {@code p / q}; and if it is {@link RoundingMode#FLOOR},
306	   * then this method is equivalent to {@link Math#floorDiv(int,int) Math.floorDiv}{@code (p, q)}.
307	   *
308	   * @throws ArithmeticException if {@code q == 0}, or if {@code mode == UNNECESSARY} and {@code a}
309	   *     is not an integer multiple of {@code b}
310	   */
311	  // Whenever both tests are cheap and functional, it's faster to use &, | instead of &&, ||
312	  @SuppressWarnings({"fallthrough", "ShortCircuitBoolean"})
313	  public static int divide(int p, int q, RoundingMode mode) {
314	    checkNotNull(mode);
315	    if (q == 0) {
316	      throw new ArithmeticException("/ by zero"); // for GWT
317	    }
318	    int div = p / q;
319	    int rem = p - q * div; // equal to p % q
320	
321	    if (rem == 0) {
322	      return div;
323	    }
324	
325	    /*
326	     * Normal Java division rounds towards 0, consistently with RoundingMode.DOWN. We just have to
327	     * deal with the cases where rounding towards 0 is wrong, which typically depends on the sign of
328	     * p / q.
329	     *
330	     * signum is 1 if p and q are both nonnegative or both negative, and -1 otherwise.
331	     */
332	    int signum = 1 | ((p ^ q) >> (Integer.SIZE - 1));
333	    boolean increment;
334	    switch (mode) {
335	      case UNNECESSARY:
336	        checkRoundingUnnecessary(rem == 0);
337	      // fall through
338	      case DOWN:
339	        increment = false;
340	        break;
341	      case UP:
342	        increment = true;
343	        break;
344	      case CEILING:
345	        increment = signum > 0;
346	        break;
347	      case FLOOR:
348	        increment = signum < 0;
349	        break;
350	      case HALF_EVEN:
351	      case HALF_DOWN:
352	      case HALF_UP:
353	        int absRem = abs(rem);
354	        int cmpRemToHalfDivisor = absRem - (abs(q) - absRem);
355	        // subtracting two nonnegative ints can't overflow
356	        // cmpRemToHalfDivisor has the same sign as compare(abs(rem), abs(q) / 2).
357	        if (cmpRemToHalfDivisor == 0) { // exactly on the half mark
358	          increment = (mode == HALF_UP || (mode == HALF_EVEN & (div & 1) != 0));
359	        } else {
360	          increment = cmpRemToHalfDivisor > 0; // closer to the UP value
361	        }
362	        break;
363	      default:
364	        throw new AssertionError();
365	    }
366	    return increment ? div + signum : div;
367	  }
