369	  /**
370	   * Returns {@code x mod m}, a non-negative value less than {@code m}. This differs from {@code x %
371	   * m}, which might be negative. This method is equivalent to {@code Math.floorMod(x, m)} except
372	   * that that method also allows negative {@code m}. {@code Math.floorMod} should be preferred when
373	   * {@code m} is known to be positive.
374	   *
375	   * <p>For example:
376	   *
377	   * {@snippet :
378	   * mod(7, 4) == 3
379	   * mod(-7, 4) == 1
380	   * mod(-1, 4) == 3
381	   * mod(-8, 4) == 0
382	   * mod(8, 4) == 0
383	   * }
384	   *
385	   * @throws ArithmeticException if {@code m <= 0}
386	   * @see <a href="https://docs.oracle.com/javase/specs/jls/se26/html/jls-15.html#jls-15.17.3">
387	   *     Remainder Operator</a>
388	   */
389	  public static int mod(int x, int m) {
390	    if (m <= 0) {
391	      throw new ArithmeticException("Modulus " + m + " must be > 0");
