495	  @SuppressWarnings("ShortCircuitBoolean")
496	  public static int checkedPow(int b, int k) {
497	    checkNonNegative("exponent", k);
498	    switch (b) {
499	      case 0:
500	        return (k == 0) ? 1 : 0;
501	      case 1:
502	        return 1;
503	      case -1:
504	        return ((k & 1) == 0) ? 1 : -1;
505	      case 2:
506	        checkNoOverflow(k < Integer.SIZE - 1, "checkedPow", b, k);
507	        return 1 << k;
508	      case -2:
509	        checkNoOverflow(k < Integer.SIZE, "checkedPow", b, k);
510	        return ((k & 1) == 0) ? 1 << k : -1 << k;
511	      default:
512	        // continue below to handle the general case
513	    }
514	    int accum = 1;
515	    while (true) {
516	      switch (k) {
517	        case 0:
518	          return accum;
519	        case 1:
520	          return Math.multiplyExact(accum, b);
521	        default:
522	          if ((k & 1) != 0) {
523	            accum = Math.multiplyExact(accum, b);
524	          }
525	          k >>= 1;
526	          if (k > 0) {
527	            checkNoOverflow(-FLOOR_SQRT_MAX_INT <= b & b <= FLOOR_SQRT_MAX_INT, "checkedPow", b, k);
528	            b *= b;
529	          }
530	      }
531	    }
