564	  /**
565	   * Returns the {@code b} to the {@code k}th power, unless it would overflow or underflow in which
566	   * case {@code Integer.MAX_VALUE} or {@code Integer.MIN_VALUE} is returned, respectively.
567	   *
568	   * @since 20.0
569	   */
570	  // Whenever both tests are cheap and functional, it's faster to use &, | instead of &&, ||
571	  @SuppressWarnings("ShortCircuitBoolean")
572	  public static int saturatedPow(int b, int k) {
573	    checkNonNegative("exponent", k);
574	    switch (b) {
575	      case 0:
576	        return (k == 0) ? 1 : 0;
577	      case 1:
578	        return 1;
579	      case -1:
580	        return ((k & 1) == 0) ? 1 : -1;
581	      case 2:
582	        if (k >= Integer.SIZE - 1) {
583	          return Integer.MAX_VALUE;
584	        }
585	        return 1 << k;
586	      case -2:
587	        if (k >= Integer.SIZE) {
588	          return Integer.MAX_VALUE + (k & 1);
589	        }
590	        return ((k & 1) == 0) ? 1 << k : -1 << k;
591	      default:
592	        // continue below to handle the general case
593	    }
594	    int accum = 1;
595	    // if b is negative and k is odd then the limit is MIN otherwise the limit is MAX
596	    int limit = Integer.MAX_VALUE + ((b >>> (Integer.SIZE - 1)) & (k & 1));
597	    while (true) {
598	      switch (k) {
599	        case 0:
600	          return accum;
601	        case 1:
602	          return saturatedMultiply(accum, b);
603	        default:
604	          if ((k & 1) != 0) {
605	            accum = saturatedMultiply(accum, b);
606	          }
607	          k >>= 1;
608	          if (k > 0) {
609	            if (-FLOOR_SQRT_MAX_INT > b | b > FLOOR_SQRT_MAX_INT) {
610	              return limit;
611	            }
612	            b *= b;
613	          }
614	      }
615	    }
616	  }
