647	  /**
648	   * Returns {@code n} choose {@code k}, also known as the binomial coefficient of {@code n} and
649	   * {@code k}, or {@link Integer#MAX_VALUE} if the result does not fit in an {@code int}.
650	   *
651	   * @throws IllegalArgumentException if {@code n < 0}, {@code k < 0} or {@code k > n}
652	   */
653	  public static int binomial(int n, int k) {
654	    checkNonNegative("n", n);
655	    checkNonNegative("k", k);
656	    checkArgument(k <= n, "k (%s) > n (%s)", k, n);
657	    if (k > (n >> 1)) {
658	      k = n - k;
659	    }
660	    if (k >= biggestBinomials.length || n > biggestBinomials[k]) {
661	      return Integer.MAX_VALUE;
662	    }
663	    switch (k) {
664	      case 0:
665	        return 1;
666	      case 1:
667	        return n;
668	      default:
669	        long result = 1;
670	        for (int i = 0; i < k; i++) {
671	          result *= n - i;
672	          result /= i + 1;
673	        }
674	        return (int) result;
675	    }
676	  }
