271	      switch ((int) b) {
272	        case 0:
273	          return (k == 0) ? 1 : 0;
274	        case 1:
275	          return 1;
276	        case -1:
277	          return ((k & 1) == 0) ? 1 : -1;
278	        case 2:
279	          return (k < Long.SIZE) ? 1L << k : 0;
280	        case -2:
281	          if (k < Long.SIZE) {
