312	    checkNonNegative("x", x);
313	    if (fitsInInt(x)) {
314	      return IntMath.sqrt((int) x, mode);
315	    }
316	    /*
317	     * Let k be the true value of floor(sqrt(x)), so that
318	     *
319	     *            k * k <= x          <  (k + 1) * (k + 1)
320	     * (double) (k * k) <= (double) x <= (double) ((k + 1) * (k + 1))
321	     *          since casting to double is nondecreasing.
322	     *          Note that the right-hand inequality is no longer strict.
323	     * Math.sqrt(k * k) <= Math.sqrt(x) <= Math.sqrt((k + 1) * (k + 1))
324	     *          since Math.sqrt is monotonic.
325	     * (long) Math.sqrt(k * k) <= (long) Math.sqrt(x) <= (long) Math.sqrt((k + 1) * (k + 1))
326	     *          since casting to long is monotonic
327	     * k <= (long) Math.sqrt(x) <= k + 1
328	     *          since (long) Math.sqrt(k * k) == k, as checked exhaustively in
329	     *          {@link LongMathTest#testSqrtOfPerfectSquareAsDoubleIsPerfect}
330	     */
331	    long guess = (long) Math.sqrt((double) x);
332	    // Note: guess is always <= FLOOR_SQRT_MAX_LONG.
333	    long guessSquared = guess * guess;
334	    // Note (2013-2-26): benchmarks indicate that, inscrutably enough, using if statements is
335	    // faster here than using lessThanBranchFree.
336	    switch (mode) {
337	      case UNNECESSARY:
338	        checkRoundingUnnecessary(guessSquared == x);
339	        return guess;
340	      case FLOOR:
341	      case DOWN:
342	        if (x < guessSquared) {
343	          return guess - 1;
344	        }
345	        return guess;
346	      case CEILING:
347	      case UP:
348	        if (x > guessSquared) {
349	          return guess + 1;
350	        }
351	        return guess;
352	      case HALF_DOWN:
353	      case HALF_UP:
354	      case HALF_EVEN:
355	        long sqrtFloor = guess - ((x < guessSquared) ? 1 : 0);
356	        long halfSquare = sqrtFloor * sqrtFloor + sqrtFloor;
357	        /*
358	         * We wish to test whether or not x <= (sqrtFloor + 0.5)^2 = halfSquare + 0.25. Since both x
359	         * and halfSquare are integers, this is equivalent to testing whether or not x <=
360	         * halfSquare. (We have to deal with overflow, though.)
361	         *
362	         * If we treat halfSquare as an unsigned long, we know that
363	         *            sqrtFloor^2 <= x < (sqrtFloor + 1)^2
364	         * halfSquare - sqrtFloor <= x < halfSquare + sqrtFloor + 1
365	         * so |x - halfSquare| <= sqrtFloor.  Therefore, it's safe to treat x - halfSquare as a
366	         * signed long, so lessThanBranchFree is safe for use.
367	         */
368	        return sqrtFloor + lessThanBranchFree(halfSquare, x);
