667	    if ((a ^ b) >= 0 | (a ^ naiveDifference) >= 0) {
668	      // If a and b have the same signs or a has the same sign as the result then there was no
669	      // overflow, return.
670	      return naiveDifference;
671	    }
672	    // we did over/under flow
673	    return Long.MAX_VALUE + ((naiveDifference >>> (Long.SIZE - 1)) ^ 1);
674	  }
