707	  /**
708	   * Returns the {@code b} to the {@code k}th power, unless it would overflow or underflow in which
709	   * case {@code Long.MAX_VALUE} or {@code Long.MIN_VALUE} is returned, respectively.
710	   *
711	   * @since 20.0
712	   */
713	  // Whenever both tests are cheap and functional, it's faster to use &, | instead of &&, ||
714	  @SuppressWarnings("ShortCircuitBoolean")
715	  public static long saturatedPow(long b, int k) {
716	    checkNonNegative("exponent", k);
717	    if (b >= -2 & b <= 2) {
718	      switch ((int) b) {
719	        case 0:
720	          return (k == 0) ? 1 : 0;
721	        case 1:
722	          return 1;
723	        case -1:
724	          return ((k & 1) == 0) ? 1 : -1;
725	        case 2:
726	          if (k >= Long.SIZE - 1) {
727	            return Long.MAX_VALUE;
728	          }
729	          return 1L << k;
730	        case -2:
731	          if (k >= Long.SIZE) {
732	            return Long.MAX_VALUE + (k & 1);
733	          }
734	          return ((k & 1) == 0) ? (1L << k) : (-1L << k);
735	        default:
736	          throw new AssertionError();
737	      }
738	    }
739	    long accum = 1;
740	    // if b is negative and k is odd then the limit is MIN otherwise the limit is MAX
741	    long limit = Long.MAX_VALUE + ((b >>> (Long.SIZE - 1)) & (k & 1));
742	    while (true) {
743	      switch (k) {
744	        case 0:
745	          return accum;
746	        case 1:
747	          return saturatedMultiply(accum, b);
748	        default:
749	          if ((k & 1) != 0) {
750	            accum = saturatedMultiply(accum, b);
751	          }
752	          k >>= 1;
753	          if (k > 0) {
754	            if (-FLOOR_SQRT_MAX_LONG > b | b > FLOOR_SQRT_MAX_LONG) {
755	              return limit;
756	            }
757	            b *= b;
758	          }
759	      }
760	    }
761	  }
