801	  /**
802	   * Returns {@code n} choose {@code k}, also known as the binomial coefficient of {@code n} and
803	   * {@code k}, or {@link Long#MAX_VALUE} if the result does not fit in a {@code long}.
804	   *
805	   * @throws IllegalArgumentException if {@code n < 0}, {@code k < 0}, or {@code k > n}
806	   */
807	  public static long binomial(int n, int k) {
808	    checkNonNegative("n", n);
809	    checkNonNegative("k", k);
810	    checkArgument(k <= n, "k (%s) > n (%s)", k, n);
811	    if (k > (n >> 1)) {
812	      k = n - k;
813	    }
814	    switch (k) {
815	      case 0:
816	        return 1;
817	      case 1:
818	        return n;
819	      default:
820	        if (n < factorials.length) {
821	          return factorials[n] / (factorials[k] * factorials[n - k]);
822	        } else if (k >= biggestBinomials.length || n > biggestBinomials[k]) {
823	          return Long.MAX_VALUE;
824	        } else if (k < biggestSimpleBinomials.length && n <= biggestSimpleBinomials[k]) {
825	          // guaranteed not to overflow
826	          long result = n--;
827	          for (int i = 2; i <= k; n--, i++) {
828	            result *= n;
829	            result /= i;
830	          }
831	          return result;
832	        } else {
833	          int nBits = log2(n, RoundingMode.CEILING);
834	
835	          long result = 1;
836	          long numerator = n--;
837	          long denominator = 1;
838	
839	          int numeratorBits = nBits;
840	          // This is an upper bound on log2(numerator, ceiling).
841	
842	          /*
843	           * We want to do this in long math for speed, but want to avoid overflow. We adapt the
844	           * technique previously used by BigIntegerMath: maintain separate numerator and
845	           * denominator accumulators, multiplying the fraction into result when near overflow.
846	           */
847	          for (int i = 2; i <= k; i++, n--) {
848	            if (numeratorBits + nBits < Long.SIZE - 1) {
849	              // It's definitely safe to multiply into numerator and denominator.
850	              numerator *= n;
851	              denominator *= i;
852	              numeratorBits += nBits;
853	            } else {
854	              // It might not be safe to multiply into numerator and denominator,
855	              // so multiply (numerator / denominator) into result.
856	              result = multiplyFraction(result, numerator, denominator);
857	              numerator = n;
858	              denominator = i;
859	              numeratorBits = nBits;
860	            }
861	          }
862	          return multiplyFraction(result, numerator, denominator);
863	        }
864	    }
865	  }
