867	  /** Returns (x * numerator / denominator), which is assumed to come out to an integral value. */
868	  static long multiplyFraction(long x, long numerator, long denominator) {
869	    if (x == 1) {
870	      return numerator / denominator;
871	    }
872	    long commonDivisor = gcd(x, denominator);
873	    x /= commonDivisor;
874	    denominator /= commonDivisor;
875	    // We know gcd(x, denominator) = 1, and x * numerator / denominator is exact,
876	    // so denominator must be a divisor of numerator.
877	    return x * (numerator / denominator);
878	  }
