1002	    if (n < 2) {
1003	      checkNonNegative("n", n);
1004	      return false;
1005	    }
1006	    if (n < 66) {
1007	      // Encode all primes less than 66 into mask without 0 and 1.
1008	      long mask =
1009	          (1L << (2 - 2))
1010	              | (1L << (3 - 2))
1011	              | (1L << (5 - 2))
1012	              | (1L << (7 - 2))
1013	              | (1L << (11 - 2))
1014	              | (1L << (13 - 2))
1015	              | (1L << (17 - 2))
1016	              | (1L << (19 - 2))
1017	              | (1L << (23 - 2))
1018	              | (1L << (29 - 2))
1019	              | (1L << (31 - 2))
1020	              | (1L << (37 - 2))
1021	              | (1L << (41 - 2))
1022	              | (1L << (43 - 2))
1023	              | (1L << (47 - 2))
1024	              | (1L << (53 - 2))
1025	              | (1L << (59 - 2))
1026	              | (1L << (61 - 2));
