1028	      return ((mask >> ((int) n - 2)) & 1) != 0;
1029	    }
1030	
1031	    if ((SIEVE_30 & (1 << (n % 30))) != 0) {
1032	      return false;
1033	    }
1034	    if (n % 7 == 0 || n % 11 == 0 || n % 13 == 0) {
1035	      return false;
1036	    }
1037	    if (n < 17 * 17) {
