1086	  private enum MillerRabinTester {
1087	    /** Works for inputs ≤ FLOOR_SQRT_MAX_LONG. */
1088	    SMALL {
1089	      @Override
1090	      long mulMod(long a, long b, long m) {
1091	        /*
1092	         * lowasser, 2015-Feb-12: Benchmarks suggest that changing this to UnsignedLongs.remainder
1093	         * and increasing the threshold to 2^32 doesn't pay for itself, and adding another enum
1094	         * constant hurts performance further -- I suspect because bimorphic implementation is a
1095	         * sweet spot for the JVM.
1096	         */
1097	        return (a * b) % m;
1098	      }
1099	
1100	      @Override
1101	      long squareMod(long a, long m) {
1102	        return (a * a) % m;
1103	      }
1104	    },
1105	    /** Works for all nonnegative signed longs. */
1106	    LARGE {
1107	      /** Returns (a + b) mod m. Precondition: {@code 0 <= a}, {@code b < m < 2^63}. */
1108	      private long plusMod(long a, long b, long m) {
1109	        return (a >= m - b) ? (a + b - m) : (a + b);
1110	      }
1111	
1112	      /** Returns (a * 2^32) mod m. a may be any unsigned long. */
1113	      private long times2ToThe32Mod(long a, long m) {
1114	        int remainingPowersOf2 = 32;
1115	        do {
1116	          int shift = min(remainingPowersOf2, Long.numberOfLeadingZeros(a));
1117	          // shift is either the number of powers of 2 left to multiply a by, or the biggest shift
1118	          // possible while keeping a in an unsigned long.
1119	          a = UnsignedLongs.remainder(a << shift, m);
1120	          remainingPowersOf2 -= shift;
1121	        } while (remainingPowersOf2 > 0);
1122	        return a;
1123	      }
1124	
1125	      @Override
1126	      long mulMod(long a, long b, long m) {
1127	        long aHi = a >>> 32; // < 2^31
1128	        long bHi = b >>> 32; // < 2^31
1129	        long aLo = a & 0xFFFFFFFFL; // < 2^32
1130	        long bLo = b & 0xFFFFFFFFL; // < 2^32
1131	
1132	        /*
1133	         * a * b == aHi * bHi * 2^64 + (aHi * bLo + aLo * bHi) * 2^32 + aLo * bLo.
1134	         *       == (aHi * bHi * 2^32 + aHi * bLo + aLo * bHi) * 2^32 + aLo * bLo
1135	         *
1136	         * We carry out this computation in modular arithmetic. Since times2ToThe32Mod accepts any
1137	         * unsigned long, we don't have to do a mod on every operation, only when intermediate
1138	         * results can exceed 2^63.
1139	         */
1140	        long result = times2ToThe32Mod(aHi * bHi /* < 2^62 */, m); // < m < 2^63
1141	        result += aHi * bLo; // aHi * bLo < 2^63, result < 2^64
1142	        if (result < 0) {
1143	          result = UnsignedLongs.remainder(result, m);
1144	        }
1145	        // result < 2^63 again
1146	        result += aLo * bHi; // aLo * bHi < 2^63, result < 2^64
1147	        result = times2ToThe32Mod(result, m); // result < m < 2^63
1148	        return plusMod(result, UnsignedLongs.remainder(aLo * bLo /* < 2^64 */, m), m);
1149	      }
1150	
1151	      @Override
1152	      long squareMod(long a, long m) {
1153	        long aHi = a >>> 32; // < 2^31
1154	        long aLo = a & 0xFFFFFFFFL; // < 2^32
1155	
1156	        /*
1157	         * a^2 == aHi^2 * 2^64 + aHi * aLo * 2^33 + aLo^2
1158	         *     == (aHi^2 * 2^32 + aHi * aLo * 2) * 2^32 + aLo^2
1159	         * We carry out this computation in modular arithmetic.  Since times2ToThe32Mod accepts any
1160	         * unsigned long, we don't have to do a mod on every operation, only when intermediate
1161	         * results can exceed 2^63.
1162	         */
1163	        long result = times2ToThe32Mod(aHi * aHi /* < 2^62 */, m); // < m < 2^63
1164	        long hiLo = aHi * aLo * 2;
1165	        if (hiLo < 0) {
1166	          hiLo = UnsignedLongs.remainder(hiLo, m);
1167	        }
1168	        // hiLo < 2^63
1169	        result += hiLo; // result < 2^64
1170	        result = times2ToThe32Mod(result, m); // result < m < 2^63
1171	        return plusMod(result, UnsignedLongs.remainder(aLo * aLo /* < 2^64 */, m), m);
1172	      }
1173	    };
