1175	    static boolean test(long base, long n) {
1176	      // Since base will be considered % n, it's okay if base > FLOOR_SQRT_MAX_LONG,
1177	      // so long as n <= FLOOR_SQRT_MAX_LONG.
1178	      return ((n <= FLOOR_SQRT_MAX_LONG) ? SMALL : LARGE).testWitness(base, n);
1179	    }
