1187	    /** Returns a^p mod m. */
1188	    private long powMod(long a, long p, long m) {
1189	      long res = 1;
1190	      for (; p != 0; p >>= 1) {
1191	        if ((p & 1) != 0) {
1192	          res = mulMod(res, a, m);
1193	        }
1194	        a = squareMod(a, m);
1195	      }
1196	      return res;
1197	    }
