1199	    /** Returns true if n is a strong probable prime relative to the specified base. */
1200	    private boolean testWitness(long base, long n) {
1201	      int r = Long.numberOfTrailingZeros(n - 1);
1202	      long d = (n - 1) >> r;
1203	      base %= n;
1204	      if (base == 0) {
1205	        return true;
1206	      }
1207	      // Calculate a := base^d mod n.
1208	      long a = powMod(base, d, n);
1209	      // n passes this test if
1210	      //    base^d = 1 (mod n)
1211	      // or base^(2^j * d) = -1 (mod n) for some 0 <= j < r.
1212	      if (a == 1) {
1213	        return true;
1214	      }
1215	      int j = 0;
1216	      while (a != n - 1) {
1217	        if (++j == r) {
1218	          return false;
1219	        }
1220	        a = squareMod(a, n);
1221	      }
1222	      return true;
1223	    }
1224	  }
