1233	   * default rounding mode: if the two nearest representable values are equally near, the one with
1234	   * the least significant bit zero is chosen. (In such cases, both of the nearest representable
1235	   * values are even integers; this method returns the one that is a multiple of a greater power of
1236	   * two.)
1237	   *
1238	   * @throws ArithmeticException if {@code mode} is {@link RoundingMode#UNNECESSARY} and {@code x}
1239	   *     is not precisely representable as a {@code double}
1240	   * @since 30.0
1241	   */
1242	  @GwtIncompatible
1243	  public static double roundToDouble(long x, RoundingMode mode) {
1244	    // Logic adapted from ToDoubleRounder.
1245	    double roundArbitrarily = (double) x;
1246	    long roundArbitrarilyAsLong = (long) roundArbitrarily;
1247	    int cmpXToRoundArbitrarily;
1248	
1249	    if (roundArbitrarilyAsLong == Long.MAX_VALUE) {
1250	      /*
1251	       * For most values, the conversion from roundArbitrarily to roundArbitrarilyAsLong is
1252	       * lossless. In that case we can compare x to roundArbitrarily using Long.compare(x,
1253	       * roundArbitrarilyAsLong). The exception is for values where the conversion to double rounds
1254	       * up to give roundArbitrarily equal to 2^63, so the conversion back to long overflows and
1255	       * roundArbitrarilyAsLong is Long.MAX_VALUE. (This is the only way this condition can occur as
1256	       * otherwise the conversion back to long pads with zero bits.) In this case we know that
1257	       * roundArbitrarily > x. (This is important when x == Long.MAX_VALUE ==
1258	       * roundArbitrarilyAsLong.)
1259	       */
1260	      cmpXToRoundArbitrarily = -1;
1261	    } else {
1262	      cmpXToRoundArbitrarily = Long.compare(x, roundArbitrarilyAsLong);
1263	    }
1264	
1265	    switch (mode) {
1266	      case UNNECESSARY:
1267	        checkRoundingUnnecessary(cmpXToRoundArbitrarily == 0);
1268	        return roundArbitrarily;
1269	      case FLOOR:
1270	        return (cmpXToRoundArbitrarily >= 0) ? roundArbitrarily : nextDown(roundArbitrarily);
1271	      case CEILING:
1272	        return (cmpXToRoundArbitrarily <= 0) ? roundArbitrarily : nextUp(roundArbitrarily);
1273	      case DOWN:
1274	        if (x >= 0) {
1275	          return (cmpXToRoundArbitrarily >= 0) ? roundArbitrarily : nextDown(roundArbitrarily);
1276	        } else {
1277	          return (cmpXToRoundArbitrarily <= 0) ? roundArbitrarily : nextUp(roundArbitrarily);
1278	        }
1279	      case UP:
1280	        if (x >= 0) {
1281	          return (cmpXToRoundArbitrarily <= 0) ? roundArbitrarily : nextUp(roundArbitrarily);
1282	        } else {
1283	          return (cmpXToRoundArbitrarily >= 0) ? roundArbitrarily : nextDown(roundArbitrarily);
1284	        }
1285	      case HALF_DOWN:
1286	      case HALF_UP:
1287	      case HALF_EVEN:
1288	        {
1289	          long roundFloor;
1290	          double roundFloorAsDouble;
1291	          long roundCeiling;
1292	          double roundCeilingAsDouble;
1293	
1294	          if (cmpXToRoundArbitrarily >= 0) {
1295	            roundFloorAsDouble = roundArbitrarily;
1296	            roundFloor = roundArbitrarilyAsLong;
1297	            roundCeilingAsDouble = nextUp(roundArbitrarily);
1298	            roundCeiling = (long) ceil(roundCeilingAsDouble);
1299	          } else {
1300	            roundCeilingAsDouble = roundArbitrarily;
1301	            roundCeiling = roundArbitrarilyAsLong;
1302	            roundFloorAsDouble = nextDown(roundArbitrarily);
1303	            roundFloor = (long) floor(roundFloorAsDouble);
1304	          }
1305	
1306	          long deltaToFloor = x - roundFloor;
1307	          long deltaToCeiling = roundCeiling - x;
1308	
1309	          if (roundCeiling == Long.MAX_VALUE) {
1310	            // correct for Long.MAX_VALUE as discussed above: roundCeilingAsDouble must be 2^63, but
1311	            // roundCeiling is 2^63-1.
1312	            deltaToCeiling++;
1313	          }
1314	
1315	          int diff = Long.compare(deltaToFloor, deltaToCeiling);
1316	          if (diff < 0) { // closer to floor
1317	            return roundFloorAsDouble;
1318	          } else if (diff > 0) { // closer to ceiling
1319	            return roundCeilingAsDouble;
1320	          }
1321	          // halfway between the representable values; do the half-whatever logic
1322	          switch (mode) {
1323	            case HALF_EVEN:
1324	              return ((DoubleUtils.getSignificand(roundFloorAsDouble) & 1L) == 0)
1325	                  ? roundFloorAsDouble
1326	                  : roundCeilingAsDouble;
1327	            case HALF_DOWN:
1328	              return (x >= 0) ? roundFloorAsDouble : roundCeilingAsDouble;
1329	            case HALF_UP:
1330	              return (x >= 0) ? roundCeilingAsDouble : roundFloorAsDouble;
1331	            default:
1332	              throw new AssertionError("impossible");
1333	          }
1334	        }
1335	    }
1336	    throw new AssertionError("impossible");
1337	  }
