72	  /** Returns {@code true} if {@code x} represents a power of two. */
73	  public static boolean isPowerOfTwo(BigInteger x) {
74	    checkNotNull(x);
75	    return x.signum() > 0 && x.getLowestSetBit() == x.bitLength() - 1;
