78	  /**
79	   * Returns the base-2 logarithm of {@code x}, rounded according to the specified rounding mode.
80	   *
81	   * @throws IllegalArgumentException if {@code x <= 0}
82	   * @throws ArithmeticException if {@code mode} is {@link RoundingMode#UNNECESSARY} and {@code x}
83	   *     is not a power of two
84	   */
85	  @SuppressWarnings("fallthrough")
86	  // TODO(kevinb): remove after this warning is disabled globally
87	  public static int log2(BigInteger x, RoundingMode mode) {
88	    checkPositive("x", checkNotNull(x));
89	    int logFloor = x.bitLength() - 1;
90	    switch (mode) {
91	      case UNNECESSARY:
92	        checkRoundingUnnecessary(isPowerOfTwo(x)); // fall through
93	      case DOWN:
94	      case FLOOR:
95	        return logFloor;
96	
97	      case UP:
98	      case CEILING:
99	        return isPowerOfTwo(x) ? logFloor : logFloor + 1;
100	
101	      case HALF_DOWN:
102	      case HALF_UP:
103	      case HALF_EVEN:
104	        if (logFloor < SQRT2_PRECOMPUTE_THRESHOLD) {
105	          BigInteger halfPower =
106	              SQRT2_PRECOMPUTED_BITS.shiftRight(SQRT2_PRECOMPUTE_THRESHOLD - logFloor);
107	          if (x.compareTo(halfPower) <= 0) {
108	            return logFloor;
109	          } else {
110	            return logFloor + 1;
111	          }
112	        }
113	        // Since sqrt(2) is irrational, log2(x) - logFloor cannot be exactly 0.5
114	        //
115	        // To determine which side of logFloor.5 the logarithm is,
116	        // we compare x^2 to 2^(2 * logFloor + 1).
117	        BigInteger x2 = x.pow(2);
118	        int logX2Floor = x2.bitLength() - 1;
119	        return (logX2Floor < 2 * logFloor + 1) ? logFloor : logFloor + 1;
120	    }
121	    throw new AssertionError();
122	  }
