31	/**
32	 * An object which joins pieces of text (specified as an array, {@link Iterable}, varargs or even a
33	 * {@link Map}) with a separator. It either appends the results to an {@link Appendable} or returns
34	 * them as a {@link String}. Example:
35	 *
36	 * {@snippet :
37	 * Joiner joiner = Joiner.on("; ").skipNulls();
38	 *  . . .
39	 * return joiner.join("Harry", null, "Ron", "Hermione");
40	 * }
41	 *
42	 * <p>This returns the string {@code "Harry; Ron; Hermione"}. Note that all input elements are
43	 * converted to strings using {@link Object#toString()} before being appended.
44	 *
45	 * <p>If neither {@link #skipNulls()} nor {@link #useForNull(String)} is specified, the joining
46	 * methods will throw {@link NullPointerException} if any given element is null.
47	 *
48	 * <p><b>Warning: joiner instances are always immutable</b>; a configuration method such as {@code
49	 * useForNull} has no effect on the instance it is invoked on! You must store and use the new joiner
50	 * instance returned by the method. This makes joiners thread-safe, and safe to store as {@code
51	 * static final} constants.
52	 *
53	 * {@snippet :
54	 * // Bad! Do not do this!
55	 * Joiner joiner = Joiner.on(',');
56	 * joiner.skipNulls(); // does nothing!
57	 * return joiner.join("wrong", null, "wrong");
58	 * }
59	 *
60	 * <p>See the Guava User Guide article on <a
61	 * href="https://github.com/google/guava/wiki/StringsExplained#joiner">{@code Joiner}</a>.
62	 *
63	 * @author Kevin Bourrillion
64	 * @since 2.0
65	 */
66	@GwtCompatible
67	public class Joiner {
68	  /** Returns a joiner which automatically places {@code separator} between consecutive elements. */
69	  public static Joiner on(String separator) {
70	    return new Joiner(separator);
71	  }
72	
73	  /** Returns a joiner which automatically places {@code separator} between consecutive elements. */
74	  public static Joiner on(char separator) {
75	    return new Joiner(String.valueOf(separator));
76	  }
