509	  // TODO(cpovirk): Rename to "toCharSequence."
510	  CharSequence toString(@Nullable Object part) {
511	    /*
512	     * requireNonNull is not safe: Joiner.on(...).join(somethingThatContainsNull) will indeed throw.
513	     * However, Joiner.on(...).useForNull(...).join(somethingThatContainsNull) *is* safe -- because
514	     * it returns a subclass of Joiner that overrides this method to tolerate null inputs.
515	     *
516	     * Unfortunately, we don't distinguish between these two cases in our public API: Joiner.on(...)
517	     * and Joiner.on(...).useForNull(...) both declare the same return type: plain Joiner. To ensure
518	     * that users *can* pass null arguments to Joiner, we annotate it as if it always tolerates null
519	     * inputs, rather than as if it never tolerates them.
520	     *
521	     * We rely on checkers to implement special cases to catch dangerous calls to join(), etc. based
522	     * on what they know about the particular Joiner instances the calls are performed on.
523	     *
524	     * (In addition to useForNull, we also offer skipNulls. It, too, tolerates null inputs, but its
525	     * tolerance is implemented differently: Its implementation avoids calling this toString(Object)
526	     * method in the first place.)
527	     */
528	    requireNonNull(part);
529	    return (part instanceof CharSequence) ? (CharSequence) part : part.toString();
530	  }
