555	  // cloned from ImmutableCollection
556	  private static int expandedCapacity(int oldCapacity, int minCapacity) {
557	    if (minCapacity < 0) {
558	      throw new IllegalArgumentException("cannot store more than Integer.MAX_VALUE elements");
559	    } else if (minCapacity <= oldCapacity) {
560	      return oldCapacity;
561	    }
562	    // careful of overflow!
563	    int newCapacity = oldCapacity + (oldCapacity >> 1) + 1;
564	    if (newCapacity < minCapacity) {
565	      newCapacity = Integer.highestOneBit(minCapacity - 1) << 1;
566	    }
567	    if (newCapacity < 0) {
568	      newCapacity = Integer.MAX_VALUE;
569	      // guaranteed to be >= newCapacity
570	    }
571	    return newCapacity;
572	  }
