34	/**
35	 * Extracts non-overlapping substrings from an input string, typically by recognizing appearances of
36	 * a <i>separator</i> sequence. This separator can be specified as a single {@linkplain #on(char)
37	 * character}, fixed {@linkplain #on(String) string}, {@linkplain #onPattern regular expression} or
38	 * {@link #on(CharMatcher) CharMatcher} instance. Or, instead of using a separator at all, a
39	 * splitter can extract adjacent substrings of a given {@linkplain #fixedLength fixed length}.
40	 *
41	 * <p>For example, this expression:
42	 *
43	 * {@snippet :
44	 * Splitter.on(',').split("foo,bar,qux")
45	 * }
46	 *
47	 * ... produces an {@code Iterable} containing {@code "foo"}, {@code "bar"} and {@code "qux"}, in
48	 * that order.
49	 *
50	 * <p>By default, {@code Splitter}'s behavior is simplistic and unassuming. The following
51	 * expression:
52	 *
53	 * {@snippet :
54	 * Splitter.on(',').split(" foo,,,  bar ,")
55	 * }
56	 *
57	 * ... yields the substrings {@code [" foo", "", "", " bar ", ""]}. If this is not the desired
58	 * behavior, use configuration methods to obtain a <i>new</i> splitter instance with modified
59	 * behavior:
60	 *
61	 * {@snippet :
62	 * private static final Splitter MY_SPLITTER = Splitter.on(',').trimResults().omitEmptyStrings();
63	 * }
64	 *
65	 * <p>Now {@code MY_SPLITTER.split("foo,,, bar ,")} returns just {@code ["foo", "bar"]}. Note that
66	 * the order in which these configuration methods are called is never significant.
67	 *
68	 * <p><b>Warning:</b> Splitter instances are immutable. Invoking a configuration method has no
69	 * effect on the receiving instance; you must store and use the new splitter instance it returns
70	 * instead.
71	 *
72	 * {@snippet :
73	 * // Do NOT do this
74	 * Splitter splitter = Splitter.on('/');
75	 * splitter.trimResults(); // does nothing!
76	 * return splitter.split("wrong / wrong / wrong");
77	 * }
78	 *
79	 * <p>For separator-based splitters that do not use {@code omitEmptyStrings}, an input string
80	 * containing {@code n} occurrences of the separator naturally yields an iterable of size {@code n +
81	 * 1}. So if the separator does not occur anywhere in the input, a single substring is returned
82	 * containing the entire input. Consequently, all splitters split the empty string to {@code [""]}
83	 * (note: even fixed-length splitters).
84	 *
85	 * <p>Splitter instances are thread-safe immutable, and are therefore safe to store as {@code static
86	 * final} constants.
87	 *
88	 * <p>The {@link Joiner} class provides the inverse operation to splitting, but note that a
89	 * round-trip between the two should be assumed to be lossy.
90	 *
91	 * <p>See the Guava User Guide article on <a
92	 * href="https://github.com/google/guava/wiki/StringsExplained#splitter">{@code Splitter}</a>.
93	 *
94	 * @author Julien Silland
95	 * @author Jesse Wilson
96	 * @author Kevin Bourrillion
97	 * @author Louis Wasserman
98	 * @since 1.0
99	 */
100	@GwtCompatible
101	public final class Splitter {
102	  private final CharMatcher trimmer;
103	  private final boolean omitEmptyStrings;
104	  private final Strategy strategy;
105	  private final int limit;
106	
107	  private Splitter(Strategy strategy) {
108	    this(strategy, false, CharMatcher.none(), Integer.MAX_VALUE);
109	  }
110	
111	  private Splitter(Strategy strategy, boolean omitEmptyStrings, CharMatcher trimmer, int limit) {
112	    this.strategy = strategy;
113	    this.omitEmptyStrings = omitEmptyStrings;
114	    this.trimmer = trimmer;
115	    this.limit = limit;
116	  }
