157	  /**
158	   * Returns a splitter that uses the given fixed string as a separator. For example, {@code
159	   * Splitter.on(", ").split("foo, bar,baz")} returns an iterable containing {@code ["foo",
160	   * "bar,baz"]}.
161	   *
162	   * @param separator the literal, nonempty string to recognize as a separator
163	   * @return a splitter, with default settings, that recognizes that separator
164	   */
165	  public static Splitter on(String separator) {
166	    checkArgument(!separator.isEmpty(), "The separator may not be the empty string.");
167	    if (separator.length() == 1) {
168	      return on(separator.charAt(0));
169	    }
170	    return new Splitter(
171	        (splitter, toSplit) ->
172	            new SplittingIterator(splitter, toSplit) {
173	              @Override
174	              int separatorStart(int start) {
175	                int separatorLength = separator.length();
176	
177	                positions:
178	                for (int p = start, last = toSplit.length() - separatorLength; p <= last; p++) {
179	                  for (int i = 0; i < separatorLength; i++) {
180	                    if (toSplit.charAt(i + p) != separator.charAt(i)) {
181	                      continue positions;
182	                    }
183	                  }
184	                  return p;
185	                }
186	                return -1;
187	              }
188	
189	              @Override
190	              int separatorEnd(int separatorPosition) {
191	                return separatorPosition + separator.length();
192	              }
193	            });
194	  }
