212	  static Splitter onPatternInternal(CommonPattern separatorPattern) {
213	    checkArgument(
214	        !separatorPattern.matcher("").matches(),
215	        "The pattern may not match the empty string: %s",
216	        separatorPattern);
217	
218	    return new Splitter(
219	        (splitter, toSplit) -> {
220	          CommonMatcher matcher = separatorPattern.matcher(toSplit);
221	          return new SplittingIterator(splitter, toSplit) {
222	            @Override
223	            int separatorStart(int start) {
224	              return matcher.find(start) ? matcher.start() : -1;
225	            }
226	
227	            @Override
228	            int separatorEnd(int separatorPosition) {
229	              return matcher.end();
230	            }
231	          };
232	        });
