275	            new SplittingIterator(splitter, toSplit) {
276	              @Override
277	              int separatorStart(int start) {
278	                int nextChunkStart = start + length;
279	                return (nextChunkStart < toSplit.length() ? nextChunkStart : -1);
280	              }
281	
282	              @Override
283	              int separatorEnd(int separatorPosition) {
284	                return separatorPosition;
285	              }
286	            });
287	  }
