468	  /**
469	   * An object that splits strings into maps as {@code Splitter} splits iterables and lists. Like
470	   * {@code Splitter}, it is thread-safe and immutable. The common way to build instances is by
471	   * providing an additional {@linkplain Splitter#withKeyValueSeparator key-value separator} to
472	   * {@link Splitter}.
473	   *
474	   * @since 10.0
475	   */
476	  public static final class MapSplitter {
477	    private static final String INVALID_ENTRY_MESSAGE = "Chunk [%s] is not a valid entry";
478	    private final Splitter outerSplitter;
479	    private final Splitter entrySplitter;
480	
481	    private MapSplitter(Splitter outerSplitter, Splitter entrySplitter) {
482	      this.outerSplitter = outerSplitter; // only "this" is passed
483	      this.entrySplitter = checkNotNull(entrySplitter);
484	    }
485	
486	    /**
487	     * Splits {@code sequence} into substrings, splits each substring into an entry, and returns an
488	     * unmodifiable map with each of the entries. For example, {@code
489	     * Splitter.on(';').trimResults().withKeyValueSeparator("=>").split("a=>b ; c=>b")} will return
490	     * a mapping from {@code "a"} to {@code "b"} and {@code "c"} to {@code "b"}.
491	     *
492	     * <p>The returned map preserves the order of the entries from {@code sequence}.
493	     *
494	     * @throws IllegalArgumentException if the specified sequence does not split into valid map
495	     *     entries, or if there are duplicate keys
496	     */
497	    public Map<String, String> split(CharSequence sequence) {
498	      Map<String, String> map = new LinkedHashMap<>();
499	      for (String entry : outerSplitter.split(sequence)) {
500	        Iterator<String> entryFields = entrySplitter.splittingIterator(entry);
501	
502	        checkArgument(entryFields.hasNext(), INVALID_ENTRY_MESSAGE, entry);
503	        String key = entryFields.next();
504	        checkArgument(!map.containsKey(key), "Duplicate key [%s] found.", key);
505	
506	        checkArgument(entryFields.hasNext(), INVALID_ENTRY_MESSAGE, entry);
507	        String value = entryFields.next();
508	        map.put(key, value);
509	
510	        checkArgument(!entryFields.hasNext(), INVALID_ENTRY_MESSAGE, entry);
511	      }
512	      return unmodifiableMap(map);
513	    }
514	  }
