520	  private abstract static class SplittingIterator extends AbstractIterator<String> {
521	    final CharSequence toSplit;
522	    final CharMatcher trimmer;
523	    final boolean omitEmptyStrings;
524	
525	    /**
526	     * Returns the first index in {@code toSplit} at or after {@code start} that contains the
527	     * separator.
528	     */
529	    abstract int separatorStart(int start);
530	
531	    /**
532	     * Returns the first index in {@code toSplit} after {@code separatorPosition} that does not
533	     * contain a separator. This method is only invoked after a call to {@code separatorStart}.
534	     */
535	    abstract int separatorEnd(int separatorPosition);
536	
537	    int offset = 0;
538	    int limit;
539	
540	    SplittingIterator(Splitter splitter, CharSequence toSplit) {
541	      this.trimmer = splitter.trimmer;
542	      this.omitEmptyStrings = splitter.omitEmptyStrings;
543	      this.limit = splitter.limit;
544	      this.toSplit = toSplit;
545	    }
546	
547	    @Override
548	    protected @Nullable String computeNext() {
549	      /*
550	       * The returned string will be from the end of the last match to the beginning of the next
551	       * one. nextStart is the start position of the returned substring, while offset is the place
552	       * to start looking for a separator.
553	       */
554	      int nextStart = offset;
555	      while (offset != -1) {
556	        int start = nextStart;
557	        int end;
558	
559	        int separatorPosition = separatorStart(offset);
560	        if (separatorPosition == -1) {
561	          end = toSplit.length();
562	          offset = -1;
563	        } else {
564	          end = separatorPosition;
565	          offset = separatorEnd(separatorPosition);
566	        }
567	        if (offset == nextStart) {
568	          /*
569	           * This occurs when some pattern has an empty match, even if it doesn't match the empty
570	           * string -- for example, if it requires lookahead or the like. The offset must be
571	           * increased to look for separators beyond this point, without changing the start position
572	           * of the next returned substring -- so nextStart stays the same.
573	           */
574	          offset++;
575	          if (offset > toSplit.length()) {
576	            offset = -1;
577	          }
578	          continue;
579	        }
580	
581	        while (start < end && trimmer.matches(toSplit.charAt(start))) {
582	          start++;
583	        }
584	        while (end > start && trimmer.matches(toSplit.charAt(end - 1))) {
585	          end--;
586	        }
587	
588	        if (omitEmptyStrings && start == end) {
589	          // Don't include the (unused) separator in next split string.
590	          nextStart = offset;
591	          continue;
592	        }
593	
594	        if (limit == 1) {
595	          // The limit has been reached, return the rest of the string as the
596	          // final item. This is tested after empty string removal so that
597	          // empty strings do not count towards the limit.
598	          end = toSplit.length();
599	          offset = -1;
600	          // Since we may have changed the end, we need to trim it again.
601	          while (end > start && trimmer.matches(toSplit.charAt(end - 1))) {
602	            end--;
603	          }
604	        } else {
605	          limit--;
606	        }
607	
608	        return toSplit.subSequence(start, end).toString();
609	      }
610	      return endOfData();
611	    }
612	  }
613	}
