      return guess;
    case CEILING:
    case UP:
      if (x > guessSquared) {
        return guess + 1;
      }
      return guess;
    case HALF_DOWN:
    case HALF_UP:
    case HALF_EVEN:
      long sqrtFloor = guess - ((x < guessSquared) ? 1 : 0);
      long halfSquare = sqrtFloor * sqrtFloor + sqrtFloor;
      /*
       * We wish to test whether or not x <= (sqrtFloor + 0.5)^2 = halfSquare + 0.25. Since both x
